import{_ as o,C as s,o as m,c as d,j as i,a as t,E as r,a2 as n}from"./chunks/framework.C21TwvGF.js";const D=JSON.parse(`{"title":"9-dars (Mentor). Raqamli transformatsiya tushunchasi","description":"","frontmatter":{"title":"9-dars (Mentor). Raqamli transformatsiya tushunchasi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":3,"link":"/mentor/8-sinf-cs/hafta-03/"},"g":9,"title":"Raqamli transformatsiya tushunchasi","lead":"Hayot, ta'lim, davlat xizmatlari va biznesni zamonaviy texnologiyalar bilan yangilash, qog'ozsiz hujjat aylanishi hamda raqamli xavfsizlik asoslari.","slide":"/slaydlar/8-sinf-cs/hafta-03/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-03/dars-3-test.html","student_link":"/8-sinf-cs/hafta-03/dars-3","tabs":[{"g":7,"link":"/mentor/8-sinf-cs/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/8-sinf-cs/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/8-sinf-cs/hafta-03/dars-3","current":true}],"prev":{"g":8,"title":"Raqamli savodxonlik va raqamli madaniyat","link":"/mentor/8-sinf-cs/hafta-03/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-03/dars-3.md","filePath":"mentor/8-sinf-cs/hafta-03/dars-3.md"}`),e={name:"mentor/8-sinf-cs/hafta-03/dars-3.md"},h={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},u={class:"blk"},y={id:"_2-dars-konspekti",tabindex:"-1"},k={class:"blk"},q={id:"_3-amaliy-mashg-ulotlar-va-keyslar",tabindex:"-1"},v={class:"blk"},z={id:"_4-tezkor-savollar-checklist",tabindex:"-1"};function b(f,a,c,p,x,_){const l=s("Icon");return m(),d("div",null,[a[12]||(a[12]=i("p",null,[i("strong",null,"Hafta:"),t(" 3 · "),i("strong",null,"Davomiyligi:"),t(" 80 daqiqa · "),i("strong",null,"Turi:"),t(" nazariya + amaliy keys-tahlil · "),i("strong",null,"II-bob"),t(", 3-dars")],-1)),i("div",h,[i("h2",g,[r(l,{name:"file-text"}),a[0]||(a[0]=t(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n('<p><strong>Maqsad:</strong> o&#39;quvchilarda raqamli transformatsiya (Digital Transformation) tushunchasi, an&#39;anaviy jarayonlarni raqamlashtirishning mohiyati, zamonaviy texnologiyalarning ta&#39;lim (e-maktab, onlayn platformalar), biznes (raqamli banklar, fintech, elektron tijorat) va davlat xizmatlaridagi (my.gov.uz, elektron litsenziyalar) o&#39;rni, qog&#39;ozsiz elektron hujjat aylanishi (EDO), elektron raqamli imzo (ERI) hamda transformatsiya jarayonida xavfsizlik va moslashuvchanlik bo&#39;yicha tizimli bilim va amaliy tushunchalarni shakllantirish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Raqamlashtirish bosqichlarini (Digitization → Digitalization → Digital Transformation) aniq farqlay oladi.</li><li>Davlat xizmatlari (my.gov.uz), ta&#39;lim (e-maktab) va biznes sohalaridagi raqamli o&#39;zgarishlarni real hayotiy misollarda tushuntira oladi.</li><li>Elektron hujjat aylanishi (EDO) va elektron raqamli imzo (ERI) qanday ishlashini biladi.</li><li>Raqamli transformatsiyaning afzalliklari (tezkorlik, qulaylik, shaffoflik, xarajatlarni tejash) va yuzaga keladigan xatarlar (kiberxavflar, tizim uzilishlari) tahlilini amalga oshira oladi.</li><li>Zamonaviy raqamli servislar orqali oddiy so&#39;rov yuborish yoki amaliy keysni bosqichma-bosqich yechish ko&#39;nikmasiga ega bo&#39;ladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>O&#39;tgan darsni takrorlash (raqamli madaniyat, feyk xabarlar). Muammoli vaziyat: «O&#39;n yil oldin pasport olish yoki bankdan pul o&#39;tkazish uchun nimalar qilish kerak edi va hozir bu jarayon qanday amalga oshiriladi?»</td></tr><tr><td>10–35 daq</td><td>Yangi mavzu: Nazariya</td><td>Raqamli transformatsiya mohiyati, 3 ta bosqich, davlat xizmatlari (my.gov.uz), ta&#39;lim, fintech, qog&#39;ozsiz hujjat aylanishi va axborot xavfsizligi</td></tr><tr><td>35–40 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>40–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>Keys-tahlil: «An&#39;anaviy maktab kutubxonasini to&#39;liq raqamli tizimga aylantirish loyihasi» va my.gov.uz portali arxitekturasi bilan tanishish</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta test/savol va mini-debat («Raqamli tizimlar inson mehnatini to&#39;liq almashtira oladimi?»)</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Asosiy tushunchalarni umumlashtirish, hafta xulosasi va uyga vazifa yo&#39;riqnomasi</td></tr></tbody></table><hr>',5))]),i("div",u,[i("h2",y,[r(l,{name:"file-text"}),a[3]||(a[3]=t(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=n(`<h3 id="_2-1-raqamli-transformatsiya-digital-transformation-nima" tabindex="-1">2.1. Raqamli transformatsiya (Digital Transformation) nima? <a class="header-anchor" href="#_2-1-raqamli-transformatsiya-digital-transformation-nima" aria-label="Permalink to &quot;2.1. Raqamli transformatsiya (Digital Transformation) nima?&quot;">​</a></h3><p><strong>Raqamli transformatsiya (Digital Transformation - DX)</strong> — bu raqamli texnologiyalarni inson hayoti, biznes faoliyati va davlat boshqaruvining barcha jabhalariga chuqur integratsiya qilish orqali mavjud jarayonlarni tubdan o&#39;zgartirish, tezlashtirish va sifat jihatidan yangi bosqichga olib chiqish jarayonidir.</p><p>Raqamlashtirishning uchta asosiy pog&#39;onasi:</p><ol><li><strong>Digitization (Raqamli ko&#39;rinishga keltirish):</strong> Jismoniy yoki qog&#39;ozdagi axborotni raqamli formatga (faylga) o&#39;tkazish. Masalan: qog&#39;oz hujjatni skanerlab PDF qilish yoki qo&#39;lda yozilgan daftarni kompyuterda Word fayliga ko&#39;chirish.</li><li><strong>Digitalization (Raqamlashtirish):</strong> Raqamli ma&#39;lumotlar yordamida mavjud ish jarayonlarini optimallashtirish. Masalan: hisobotlarni qog&#39;ozda emas, balki Excel yoki elektron pochta orqali almashish.</li><li><strong>Digital Transformation (Raqamli transformatsiya):</strong> Butun tizim, madaniyat va xizmat ko&#39;rsatish modelini zamonaviy texnologiyalar (AI, bulut, API, mobil ilovalar) asosida tubdan qayta qurish. Masalan: jismoniy bankka bormasdan, mobil ilova orqali bir necha soniyada hisob ochish, kredit olish va to&#39;lovlarni amalga oshirish.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span>| 1. Digitization        --&gt;  Qog&#39;ozni PDF / faylga aylantirish |</span></span>
<span class="line"><span>| 2. Digitalization      --&gt;  Jarayonni kompyuterda bajarish    |</span></span>
<span class="line"><span>| 3. Digital Transf.     --&gt;  Yangi biznes-model va avtomatika  |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span></code></pre></div><h3 id="_2-2-davlat-xizmatlarida-raqamli-transformatsiya" tabindex="-1">2.2. Davlat xizmatlarida raqamli transformatsiya <a class="header-anchor" href="#_2-2-davlat-xizmatlarida-raqamli-transformatsiya" aria-label="Permalink to &quot;2.2. Davlat xizmatlarida raqamli transformatsiya&quot;">​</a></h3><p>Ilgari biror ma&#39;lumotnoma (yashash joyidan, o&#39;qish joyidan yoki sudlanmaganlik haqida) olish uchun turli idoralarga borish, navbatda turish va bir necha kun kutish talab etilardi.</p><p>Hozirgi davlat xizmatlari ekotizimi:</p><ul><li><strong>my.gov.uz (Yagona interaktiv davlat xizmatlari portali):</strong> 500 dan ortiq davlat xizmatlari yagona darcha orqali elektron taqdim etiladi.</li><li><strong>Elektron raqamli imzo (ERI):</strong> Jismoniy va yuridik shaxslarning elektron hujjatdagi shaxsiy imzosining qonuniy ekvivalenti bo&#39;lib, hujjatning haqiqiyligini kafolatlaydi.</li><li><strong>OneID (Yagona identifikatsiya tizimi):</strong> Barcha davlat va rasmiy axborot tizimlariga bitta login va parol orqali xavfsiz kirish imkonini beruvchi tizim.</li><li><strong>Qog&#39;ozsiz hujjat aylanishi (EDO):</strong> Tashkilotlar o&#39;rtasida shartnomalar, schyot-fakturalar va buyruqlarni qog&#39;ozsiz, ERI orqali tasdiqlangan elektron shaklda uzatish.</li></ul><h3 id="_2-3-ta-lim-va-biznes-sohalaridagi-transformatsiya" tabindex="-1">2.3. Ta&#39;lim va biznes sohalaridagi transformatsiya <a class="header-anchor" href="#_2-3-ta-lim-va-biznes-sohalaridagi-transformatsiya" aria-label="Permalink to &quot;2.3. Ta&#39;lim va biznes sohalaridagi transformatsiya&quot;">​</a></h3><ol><li><p><strong>Ta&#39;limda:</strong></p><ul><li><strong>e-maktab (Kundalik.com):</strong> Elektron jurnallar, o&#39;quvchilar baholari, dars jadvallari va ota-onalar uchun real vaqt monitoringi.</li><li><strong>Onlayn ta&#39;lim platformalari (Coursera, edX, Khan Academy):</strong> Dunyoning istalgan nuqtasidan sifatli bilim olish imkoniyati.</li><li><strong>Elektron darsliklar va virtual laboratoriyalar:</strong> Og&#39;ir qog&#39;oz darsliklar o&#39;rniga interaktiv multimedia vositalari.</li></ul></li><li><p><strong>Biznes va moliya sohasida (Fintech):</strong></p><ul><li><strong>Raqamli banklar va to&#39;lov tizimlari (Click, Payme, Uzum, Anorbank):</strong> 24/7 rejimida kartadan kartaga pul o&#39;tkazish, kommunal to&#39;lovlar, omonat ochish.</li><li><strong>Elektron tijorat (E-commerce):</strong> Uzum Market, Amazon kabi platformalarda mahsulotlarni uydan chiqmasdan xarid qilish va yetkazib berish.</li><li><strong>Avtomatlashtirilgan kuryerlik va logistika:</strong> Buyurtmaning qayerda kelayotganini xaritada real vaqtda kuzatish (GPS tracking).</li></ul></li></ol><h3 id="_2-4-raqamli-transformatsiyaning-afzalliklari-va-qiyinchiliklari" tabindex="-1">2.4. Raqamli transformatsiyaning afzalliklari va qiyinchiliklari <a class="header-anchor" href="#_2-4-raqamli-transformatsiyaning-afzalliklari-va-qiyinchiliklari" aria-label="Permalink to &quot;2.4. Raqamli transformatsiyaning afzalliklari va qiyinchiliklari&quot;">​</a></h3><p><strong>Afzalliklari:</strong></p><ul><li><strong>Tezkorlik:</strong> Bir necha kunlik jarayonlar soniyalar ichida hal bo&#39;ladi.</li><li><strong>Shaffoflik va korrupsiyaning oldini olish:</strong> Inson omili aralashmaydigan avtomatlashtirilgan tizimlarda adolatli xizmat ko&#39;rsatiladi.</li><li><strong>Iqtisodiy tejamkorlik:</strong> Tonnalab qog&#39;oz, printer bo&#39;yog&#39;i, arxiv xonalari va transport xarajatlari tejaladi.</li><li><strong>24/7 qulaylik:</strong> Xizmatlardan haftaning istalgan kuni va soatida foydalanish mumkin.</li></ul><p><strong>Xavflar va qiyinchiliklar:</strong></p><ul><li><strong>Kiberxavfsizlik xavfi:</strong> Barcha ma&#39;lumotlar serverlarda saqlangani sababli hakerlik hujumlari va ma&#39;lumotlar sizib chiqish xavfi ortadi.</li><li><strong>Tizim nosozliklari:</strong> Elektr energiyasi yoki internet uzilib qolsa, butun ish to&#39;xtab qolishi mumkin.</li><li><strong>Raqamli tengsizlik (Digital Divide):</strong> Barcha insonlarda ham zamonaviy qurilmalar yoki yuqori tezlikdagi internet bo&#39;lmasligi mumkin.</li><li><strong>Xodimlarning tayyor emasligi:</strong> Yangi dasturlar bilan ishlash uchun odamlarni qayta o&#39;qitish zarurati.</li></ul><hr>`,17))]),i("div",k,[i("h2",q,[r(l,{name:"file-text"}),a[6]||(a[6]=t(" 3. Amaliy mashg'ulotlar va keyslar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-mashg-ulotlar-va-keyslar","aria-label":`Permalink to "<Icon name="file-text" /> 3. Amaliy mashg'ulotlar va keyslar"`},"​",-1))]),a[8]||(a[8]=n('<h3 id="_1-mashq-bosqichlarni-ajratish-digitization-vs-digitalization-vs-dx" tabindex="-1">1-mashq. Bosqichlarni ajratish (Digitization vs Digitalization vs DX) <a class="header-anchor" href="#_1-mashq-bosqichlarni-ajratish-digitization-vs-digitalization-vs-dx" aria-label="Permalink to &quot;1-mashq. Bosqichlarni ajratish (Digitization vs Digitalization vs DX)&quot;">​</a></h3><p><strong>Vazifa:</strong> Quyidagi holatlarning qaysi biri Digitization, qaysi biri Digitalization va qaysi biri Raqamli Transformatsiya ekanligini aniqlang:</p><ol><li>Maktab kutubxonachisi barcha kitoblar ro&#39;yxatini daftardan Excel jadvaliga ko&#39;chirib yozib chiqdi.</li><li>Har bir kitobga QR-kod yopishtirildi va o&#39;quvchi kitobni qaytarganda skaner orqali tizimga avtomatik belgilandi.</li><li>Maxsus mobil ilova yaratildi: o&#39;quvchi istalgan kitobni ilovadan qidiradi, uning bandligini ko&#39;radi, elektron nusxasini o&#39;qiydi yoki audio formatini tinglaydi, sun&#39;iy intellekt esa unga qiziqishiga qarab yangi kitoblar tavsiya qiladi.</li></ol><p><strong>Yechim:</strong></p><ol><li><strong>Digitization</strong> — ma&#39;lumot qog&#39;ozdan raqamli faylga ko&#39;chirildi.</li><li><strong>Digitalization</strong> — mavjud kutubxona jarayoni kompyuter va skaner yordamida tezlashtirildi.</li><li><strong>Raqamli transformatsiya (DX)</strong> — kitob o&#39;qish va kutubxona xizmati tubdan yangi, to&#39;liq avtomatlashgan, sun&#39;iy intellektga asoslangan raqamli formatga o&#39;tdi.</li></ol><hr><h3 id="_2-mashq-my-gov-uz-va-an-anaviy-xizmat-tahlili" tabindex="-1">2-mashq. my.gov.uz va an&#39;anaviy xizmat tahlili <a class="header-anchor" href="#_2-mashq-my-gov-uz-va-an-anaviy-xizmat-tahlili" aria-label="Permalink to &quot;2-mashq. my.gov.uz va an&#39;anaviy xizmat tahlili&quot;">​</a></h3><p><strong>Vazifa:</strong> Yashash joyidan ma&#39;lumotnoma olishning «Eski usuli» va «my.gov.uz orqali yangi usuli»ni quyidagi parametrlar bo&#39;yicha jadvalda taqqoslang: vaqt, xarajat, kerakli qog&#39;ozlar soni, inson omili.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>Parametr</th><th>Eski usul (an&#39;anaviy)</th><th>my.gov.uz orqali (raqamli)</th></tr></thead><tbody><tr><td>Sarflanadigan vaqt</td><td>1–3 kun (mahalla va hokimiyatga borish)</td><td>1–2 daqiqa</td></tr><tr><td>Transport va boshqa xarajatlar</td><td>Yo&#39;l haqi, qog&#39;oz nusxalari (kopiya)</td><td>0 so&#39;m (uydan turib)</td></tr><tr><td>Kerakli hujjatlar</td><td>Pasport nusxasi, ariza qog&#39;ozi, ma&#39;lumotnoma blankasi</td><td>Shaxsiy JShShIR orqali avtomatik ma&#39;lumot</td></tr><tr><td>Inson omili</td><td>Mansabdor shaxsning kayfiyati, navbatlar, xatoliklar</td><td>100% avtomatlashgan, QR-kodli rasmiy hujjat</td></tr></tbody></table><hr>',11))]),i("div",v,[i("h2",z,[r(l,{name:"file-text"}),a[9]||(a[9]=t(" 4. Tezkor savollar (Checklist) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-savollar-checklist","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor savollar (Checklist)"'},"​",-1))]),a[11]||(a[11]=n("<ol><li>Digitization va Raqamli transformatsiyaning farqi nimada? <ul><li><strong>Javob:</strong> Digitization shunchaki qog&#39;ozdagi axborotni raqamli faylga ko&#39;chirishdir. Raqamli transformatsiya esa butun xizmat va jarayonni yangi texnologiyalar yordamida tubdan avtomatlashtirish va yangilashdir.</li></ul></li><li>Elektron raqamli imzo (ERI) nima uchun kerak? <ul><li><strong>Javob:</strong> Elektron hujjatlarning haqiqiyligini tasdiqlash va qonuniy kuch berish uchun jismoniy imzo o&#39;rnida ishlatiladi.</li></ul></li><li>OneID tizimining vazifasi nima? <ul><li><strong>Javob:</strong> Davlat axborot portallariga yagona identifikatsiya orqali xavfsiz kirishni ta&#39;minlash.</li></ul></li><li>Raqamli transformatsiya korrupsiyani qanday kamaytiradi? <ul><li><strong>Javob:</strong> Inson omilini kamaytiradi; xizmatlar avtomatik tarzda shaffof algoritmlar asosida ko&#39;rsatiladi va har bir harakat tizimda qayd etiladi.</li></ul></li><li>Raqamli transformatsiyaning eng katta xavfi nima? <ul><li><strong>Javob:</strong> Kiberxavfsizlik tahdidlari (hakerlik hujumlari, shaxsiy ma&#39;lumotlarning tarqalishi) va tizimning texnik nosozliklarga bog&#39;liqligi.</li></ul></li></ol>",1))])])}const T=o(e,[["render",b]]);export{D as __pageData,T as default};
